# Restore and replay exact locally tested original Farmer's Homestead V1 source.
import base64,gzip,hashlib,runpy
from pathlib import Path
here=Path(__file__).resolve().parent
source=gzip.decompress(base64.b64decode("""""",validate=True))
assert hashlib.sha256(source).hexdigest()=="5951f82c9c592e267c3172c7966a8c191eb076cef467567313e891e75b49322f"
script=here/"build_farm.py"
if script.exists() and script.read_bytes()!=source: raise RuntimeError("Preserve manually edited source before replay")
script.write_bytes(source)
runpy.run_path(str(script),run_name="__main__")
assert hashlib.sha256(gzip.decompress((here/"prefab-extension/farmers_homestead.nbt").read_bytes())).hexdigest()=="707fe282db0a76252970e64d3fef03aba3b3f2d0ca8de042f25dd5ba4eef76c6"
